trace=Path(sys.argv[1]).read_text(encoding='ascii',errors='replace').splitlines();checks={'trace_exact':trace==expected,'bad_multiple_writers_break_version_meaning':all(x in trace for x in ['BAD_ACTIVE_WRITERS=02','BAD_VERSION_WHILE_ACTIVE=02','BAD_EVEN_WHILE_ACTIVE=1']),'good_single_writer_condition':all(x in trace for x in ['GOOD_MAX_ACTIVE=01','GOOD_BSP_COMPLETE=1','GOOD_AP_COMPLETE=1','GOOD_FINAL_VERSION=04']),'two_cpu_participation':all(x in trace for x in ['AP_READY=1','AP_DONE=1'])};out={'format':'C005_P12_EVALUATION_V1','passed':all(checks.values()),'checks':checks,'trace':trace};Path(sys.argv[2]).write_text(json.dumps(out,indent=2)+'\n');print(json.dumps(out,indent=2));raise SystemExit(0 if out['passed'] else 1)
